 if ( ! defined( 'WP_UNINSTALL_PLUGIN' ) ) { exit; } /* Keep the settings, the Extra Options forms and the checkout fields unless the person turned on Nexvio > Settings > Data > Delete everything. */ if ( 'yes' !== get_option( 'nexvio_delete_data', 'no' ) ) { return; } foreach ( array( 'nexvio_disabled_widgets', 'nexvio_wishlist_page', 'nexvio_wishlist_page_pending', 'nexvio_wishlist_guests', 'nexvio_wishlist_days', 'nexvio_per_page', 'nexvio_do_activation_redirect', 'nexvio_auto_related', 'nexvio_related_title', 'nexvio_related_limit', 'nexvio_related_orderby', 'nexvio_related_layout', 'nexvio_cart', 'nexvio_filters', 'nexvio_filter_style', 'nexvio_epo_settings', 'nexvio_checkout_fields', 'nexvio_checkout_page_pending', 'nexvio_features_off', 'nexvio_defaults_103', 'nexvio_delete_data', ) as $nexvio_option ) { delete_option( $nexvio_option ); } delete_transient( 'nexvio_price_bounds' ); foreach ( get_posts( array( 'post_type' => 'nexvio_epo', 'post_status' => 'any', 'numberposts' => -1, 'fields' => 'ids' ) ) as $nexvio_form_id ) { wp_delete_post( $nexvio_form_id, true ); }